head.script:
scwin.trigger1_onclick = function(e) {
    gv1.setColumnOrder(["2", "3", "0", "1"]);
};
scwin.trigger2_onclick = function(e) {
    gv1.setColumnOrder(["1", "2", "3", "0"]);
};
scwin.checkValueChanged = function(firstVals, secondVals) {}
scwin.getVal = function() {
    return WebSquare.wUnit.getDomById('gv1_head_table').firstChild.childNodes[0].id + WebSquare.wUnit.getDomById('gv1_head_table').firstChild.childNodes[1].id +
        WebSquare.wUnit.getDomById('gv1_head_table').firstChild.childNodes[2].id + WebSquare.wUnit.getDomById('gv1_head_table').firstChild.childNodes[3].id;
}
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#gv1_column3', 'drag-n-drop', {
        dx: 60,
        dy: 0
    })
}

scwin.setVal1 = function() {
	firstVals = scwin.getVal();
}
scwin.setVal2 = function() {
	secondVals = scwin.getVal();
}
scwin.checkVal1 = function() {
	return firstVals != secondVals;
}

scwin.checkVal1 = function() {
	return firstVals != secondVals;
}

scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setVal1()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setVal2()");

    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");

    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('gv1_cell_2_1').innerText", "**********");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('gv1_cell_3_1').innerText", "((((((((((");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('gv1_cell_4_1').innerText", "zxczczxc");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('gv1_cell_5_1').innerText", "2");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

